#' @param group_key  Integer vector of length N: group identifier for
#'   centring.  \code{NA_integer_} or \code{0} → row is excluded from all
#'   group means and contributes 0 to the output.
#'
#' @return N × (K × p) numeric matrix.  Column order: for each covariate j
#'   (j = 0 … p-1), the K columns \code{ind_mat[,k] * x_centred[,j]}
#'   for k = 0 … K-1 are contiguous.  Column names are set by the R caller.
#'
#' @noRd
build_cov_interactions_cpp <- function(cov_mat, ind_mat, group_key) {
    .Call(`_fixes_build_cov_interactions_cpp`, cov_mat, ind_mat, group_key)
}

#' K-way fixed-effects demeaning by alternating projections
#'
#' Demeans each column of \code{M} with respect to all fixed-effect
#' dimensions simultaneously (Gauss-Seidel sweeps over the FE dimensions
#' until the largest subtracted group mean falls below \code{tol} times the
#' column scale). With a single FE dimension one sweep is exact.
#'
#' Columns are independent, so they are distributed over OpenMP threads;
#' the per-column arithmetic is unchanged by the thread count, making the
#' result bit-identical for any \code{nthreads}.
#'
#' \code{fe_ids} must contain dense 0-based level indices per dimension and
#' the rows must already form the final estimation sample (NA rows,
#' zero-weight rows, and singleton FE levels removed by the caller, see
#' \code{.fit_fe_ols()}).
#'
#' With observation weights (\code{w} of length N), group means become
#' weighted means (sum of w*x over sum of w per level), i.e. the projection
#' onto the fixed effects under weighted least squares. An empty \code{w}
#' keeps the unweighted path with integer counts, bit-identical to before.
#'
#' @param M Numeric matrix (N x C): columns to demean (outcome + regressors).
#' @param fe_ids Integer matrix (N x Q): 0-based FE level index per dimension.
#' @param n_levels Integer vector (length Q): number of levels per dimension.
#' @param w Numeric vector: observation weights (length N), or length 0 for
#'   the unweighted case. Must be strictly positive.
#' @param tol Relative convergence tolerance on subtracted group means.
#' @param max_iter Maximum number of full sweeps per column.
#' @param nthreads Number of OpenMP threads (ignored without OpenMP).
#' @param scale_sqrt_w Logical: if TRUE and \code{w} is non-empty, multiply
#'   each demeaned row \code{k} by \code{sqrt(w[k])} in place before returning.
#'
#' @return A list with \code{M} (demeaned copy) and \code{converged}.
#'
#' @noRd
demean_kway_cpp <- function(M, fe_ids, n_levels, w, tol, max_iter, nthreads, scale_sqrt_w = FALSE) {
    .Call(`_fixes_demean_kway_cpp`, M, fe_ids, n_levels, w, tol, max_iter, nthreads, scale_sqrt_w)
}

